<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Restock Admin</title><link rel="stylesheet" href="/assets/style.css"></head><body class="admin-body"><div class="admin-wrap"><header class="admin-head"><div class="brand">RESTOCK<span>.</span> <small>ADMIN</small></div><div class="muted">Notification overview</div></header><h1>Overview</h1><p class="muted">Your latest 300 subscriptions, updated on refresh.</p><div class="stats"><div><span>Total requests</span><strong><?= (int)($stats['total']??0) ?></strong></div><div><span>Waiting</span><strong><?= (int)($stats['pending']??0) ?></strong></div><div><span>Queued</span><strong><?= (int)($stats['queued']??0) ?></strong></div><div><span>Notified</span><strong><?= (int)($stats['notified']??0) ?></strong></div></div><div class="table-card"><div class="table-title">Subscriptions</div><div class="table-scroll"><table><thead><tr><th>ID</th><th>Email</th><th>SKU</th><th>Status</th><th>Requested</th><th>Notified</th><th>Attempts</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= h($r['email']) ?></td><td><?= h($r['sku']) ?></td><td><span class="pill <?= h($r['status']) ?>"><?= h(ucfirst($r['status'])) ?></span></td><td><?= h($r['created_at']) ?></td><td><?= h($r['notified_at']??'—') ?></td><td><?= (int)($r['attempts']??0) ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7">No requests yet. Share your /embed form to get started.</td></tr><?php endif; ?></tbody></table></div></div></div></body></html>